package vn.covie.outbox.application; import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; @Component public class OutboxScheduler {private final OutboxProcessor processor;private final int max;public OutboxScheduler(OutboxProcessor processor,@Value("${covie.outbox.max-events-per-poll:50}")int max){this.processor=processor;this.max=max;}@Scheduled(fixedDelayString="${covie.outbox.poll-delay-ms:500}")public void poll(){for(int i=0;i<max&&processor.processOne();i++);}}
